"const sql = require('mssql');

const dbConfig = {
  server: 'localhost',
  database: 'ControlabIA',
  user: 'controlab_user',
  password: 'Delicia1.',
  port: 1433,
  options: {
    encrypt: false,
    trustServerCertificate: true,
    enableArithAbort: true
  }
};

async function createTable() {
  try {
    const pool = await sql.connect(dbConfig);
    console.log('Connected!');

    // 1. Check if table already exists
    const checkTable = await pool.request().query(`
      SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'proveedores'
    `);

    if (checkTable.recordset.length === 0) {
      console.log('Creating table proveedores...');
      await pool.request().query(`
        CREATE TABLE proveedores (
          id INT IDENTITY(1,1) PRIMARY KEY,
          nombre NVARCHAR(150) UNIQUE NOT NULL,
          creado_por NVARCHAR(100) DEFAULT 'admin',
          fecha_creacion DATETIME DEFAULT GETDATE(),
          fecha_actualizacion DATETIME DEFAULT GETDATE()
        )
      `);
      console.log('Table proveedores created!');
    } else {
      console.log('Table proveedores already exists!');
    }

    // 2. Seed default values
    const checkCount = await pool.request().query("SELECT COUNT(*) as count FROM proveedores");
    if (checkCount.recordset[0].count === 0) {
      console.log('Seeding default providers...');
      await pool.request().query(`
        SET IDENTITY_INSERT proveedores ON;
        INSERT INTO proveedores (id, nombre) VALUES 
        (1, 'Lab Supplies C.A.'),
        (2, 'Meditek Venezuela'),
        (3, 'BioAnalítica S.A.'),
        (4, 'Química Avanzada');
        SET IDENTITY_INSERT proveedores OFF;
      `);
      console.log('Default providers seeded!');
    }

    await pool.close();
  } catch (e) {
    console.error(e);
  }
}

createTable();
"

