"const http = require('http');

const options = {
  hostname: 'localhost',
  port: 5000,
  path: '/api/health',
  method: 'GET'
};

const req = http.request(options, (res) => {
  let body = '';
  res.on('data', (chunk) => {
    body += chunk;
  });

  res.on('end', () => {
    try {
      const data = JSON.parse(body);
      console.log('Server Health Status:');
      console.log('Status Code:', res.statusCode);
      console.log('Response Body:', data);
    } catch (e) {
      console.log('Failed to parse JSON. Body was:', body);
    }
  });
});

req.on('error', (error) => {
  console.error('Error connecting to server:', error.message);
});

req.end();
"

"const { execSync } = require('child_process');

try {
  console.log('Finding process on port 5000...');
  const output = execSync('netstat -ano | findstr :5000').toString();
  console.log('Netstat output:', output);

  const lines = output.trim().split('\n');
  const pids = new Set();

  lines.forEach(line => {
    const parts = line.trim().split(/\s+/);
    if (parts.length >= 5) {
      const state = parts[3];
      const pid = parts[4];
      if (state === 'LISTENING') {
        pids.add(pid);
      }
    }
  });

  if (pids.size === 0) {
    console.log('No active listening process found on port 5000.');
  } else {
    pids.forEach(pid => {
      console.log(`Killing process with PID: ${pid}...`);
      try {
        execSync(`taskkill /F /PID ${pid}`);
        console.log(`Process ${pid} killed successfully.`);
      } catch (err) {
        console.error(`Failed to kill process ${pid}:`, err.message);
      }
    });
  }
} catch (error) {
  console.error('Error finding/killing process:', error.message);
}
"

